import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Grok Bot","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/grok/grok-bot.md","filePath":"zh/products/ai-coding/grok/grok-bot.md","lastUpdated":1787110548000}'),i={name:"zh/products/ai-coding/grok/grok-bot.md"};function n(l,t,s,d,g,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="grok-bot" tabindex="-1">Grok Bot <a class="header-anchor" href="#grok-bot" aria-label="Permalink to &quot;Grok Bot&quot;">​</a></h1><blockquote><p><strong>Grok Bot</strong> 是 xAI 的常驻同事产品。官方定义（<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a>）： &quot;Bots are AI teammates you can give real work to. Bots can sign and use apps and websites just like you do on a persistent cloud computer.&quot;</p><p>本页只根据 <a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot</a>、<a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a>、<a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">x.ai/news/introducing-grok-bot</a> 画产品地图。它<strong>不是</strong> Grok Build CLI 教程——CLI 在 <a href="./grok-cli.html">grok-cli.md</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>目标：</strong> 把 Grok Bot 和 Grok Build / grok.com 聊天 / Imagine / Build Mode 分开，并指向官方文档里的安装、共享电脑和审批。</p><p><strong>非目标：</strong> 再抄一遍官方 get-started、臆造配额，或把三方博客里 docs.x.ai / x.ai / grok.com 没有的说法写成事实。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>文档和 App 里，<strong>一个 Bot = 一个持久的、有名字的 agent</strong>（<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">overview</a>）。你像给同事发消息那样派活。合上笔记本之后，云电脑上的工作继续跑（<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>）。</p><p>官方相对聊天助手的差异（<a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">overview</a>、<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>）：</p><ul><li>每个 Bot 跑在一台带浏览器、文件系统和终端的<strong>持久云 VM</strong> 上。</li><li>有 connector / MCP 就用；没有干净 API 的网站走 computer use。</li><li>多个 Bot <strong>共用一台按用户划分的电脑</strong>，可以并行、互相发消息、交接。</li><li>可以跟着你演示一遍工作流，存成 <strong>routine</strong>。</li><li>具名 Bot 跨轮次保留记忆、文件、浏览器会话和偏好。</li></ul><table tabindex="0"><thead><tr><th></th><th>Grok（聊天）</th><th>Grok Build</th><th>Grok Bot</th></tr></thead><tbody><tr><td>干什么</td><td>对话、搜索、语音、Imagine</td><td>改本地 / CI 里的真实仓库</td><td>在 App 和网站里把活干完</td></tr><tr><td>电脑</td><td>没有自己的电脑</td><td>你的机器（可选沙箱）</td><td>每个用户一台持久<strong>云</strong>电脑</td></tr><tr><td>合上笔记本就停？</td><td>是（它是聊天）</td><td>是（进程在本地）</td><td>否——云上继续</td></tr><tr><td>官方入口</td><td><a href="https://grok.com" target="_blank" rel="noreferrer">grok.com</a></td><td><code>grok</code></td><td>桌面 + iOS（<a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a>）</td></tr></tbody></table><p>发布公告（<a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">2026-08-11</a>）写明 Grok Bot 处于 <strong>beta</strong>。</p><h2 id="谁能用" tabindex="-1">谁能用 <a class="header-anchor" href="#谁能用" aria-label="Permalink to &quot;谁能用&quot;">​</a></h2><p><a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a> 列出的资格：</p><ul><li>SuperGrok Heavy</li><li>Cursor Ultra</li><li>Cursor Teams Premium（用 Cursor 账号登录）</li></ul><p><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a> 补充：&quot;Already on Cursor Ultra or SuperGrok Heavy? Grok Bot is included.&quot; <a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">发布公告</a> 里企业用户走 waitlist；<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a> 说团队 / 企业放量因组织而异。</p><p><strong>认证走 Cursor</strong>，不是 <code>grok login</code>。Grok Bot 要求云端数据存储，不支持 Legacy Privacy Mode（<a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a>、<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>）。</p><h3 id="平台-faq" tabindex="-1">平台（<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>） <a class="header-anchor" href="#平台-faq" aria-label="Permalink to &quot;平台（[faq](https://docs.x.ai/grok-bot/faq)）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>发布时支持</th><th>发布时不支持</th></tr></thead><tbody><tr><td>macOS（Apple silicon 与 Intel）</td><td>Linux 桌面</td></tr><tr><td>Windows（x64 与 Arm64）</td><td>Android</td></tr><tr><td>iOS 18 及以上的 iPhone</td><td>iPad</td></tr></tbody></table><p>同一套 Bot 和对话在已登录设备之间同步。</p><h2 id="共享的云电脑" tabindex="-1">共享的云电脑 <a class="header-anchor" href="#共享的云电脑" aria-label="Permalink to &quot;共享的云电脑&quot;">​</a></h2><p>账号下每个 Bot 用的是<strong>同一台</strong>电脑（<a href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noreferrer">computer-and-apps</a>）：</p><ul><li>浏览器 cookie 和登录会话共享</li><li>文件对每个 Bot 可见</li><li>命令行凭证共享</li><li>一个 Bot 可以从另一个 Bot 留下的工作接着做</li></ul><p>电脑挂在<strong>用户账号</strong>上，不挂在单个 Bot 上。官方警告写了两遍：<strong>不要把不同 Bot 当成安全边界</strong>。</p><p>每个 Bot 在这台共享电脑上有自己的屏幕，所以多个 Bot 可以并行用浏览器和桌面工具。一个 Bot 在自己的屏幕上同一时刻只能跑一个 computer-use 任务。屏幕是工作面，<strong>不是</strong>独立安全域。</p><p>持久项目文件放在共享工作区 <code>/workspace</code>。临时目录、手工装的包、未提交的应用状态都按可丢弃处理。</p><p>云电脑和你面前的 Mac / Windows <strong>是分开的</strong>。本机命令策略在 <strong>Settings → General → Agent → Execution on Local Computer</strong>，默认 <strong>Ask every time</strong>（<a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">approvals</a>）。这些设置挡不住 Bot 用它自己的云电脑。</p><h2 id="上手-官方顺序" tabindex="-1">上手（官方顺序） <a class="header-anchor" href="#上手-官方顺序" aria-label="Permalink to &quot;上手（官方顺序）&quot;">​</a></h2><p>按 <a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">get-started</a> 走。压缩如下：</p><ol><li>从 <a href="https://x.ai/bot" target="_blank" rel="noreferrer">Grok Bot 入口页</a> 装桌面 App（macOS：拖进 Applications；Windows：跑安装器）。</li><li>在 App 打开的浏览器窗口里用 Cursor 账号登录。</li><li>创建一个 Bot：短名字、一个主职、它该怎么干活。官方建议：职责收窄的 Bot 好过一个万能 Bot。</li><li>第一次派活要写清结果、来源、约束、交付物、何时停下来给你看。</li><li>网站要密码、passkey、二次验证或 CAPTCHA 时，打开 <strong>Agent Computer</strong>，自己接管、只做这一步，再交还控制权。<strong>不要把密码或一次性验证码贴进聊天。</strong></li></ol><p>当前 App 里 connector 显示为 <strong>Plugins</strong>： <strong>Settings → Plugins</strong>。聊天里用 <code>@</code> 挂上 connector，用 <code>/</code> 引用已存 skill。有 connector 优先用 connector；没有的服务再用浏览器。</p><h2 id="skill-和-routine" tabindex="-1">Skill 和 routine <a class="header-anchor" href="#skill-和-routine" aria-label="Permalink to &quot;Skill 和 routine&quot;">​</a></h2><p>官方分法（<a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a>）：</p><ul><li><strong>skill</strong> 描述「这件事怎么做」。</li><li><strong>routine</strong> 把一条工作流派给某个 Bot，并告诉它何时跑——按日程，或（若支持）按事件。</li></ul><p>先在一次性真实任务上试过 skill，再做成 routine。</p><p><strong>Teach a task</strong>（若该账号已开放）从电脑视图录一段浏览器流程，上限十分钟。放量可能是逐步的。</p><p>删除 Bot 会去掉它的档案、对话和 routine。共享电脑上的文件和登录可能还在。</p><h2 id="该设的审批" tabindex="-1">该设的审批 <a class="header-anchor" href="#该设的审批" aria-label="Permalink to &quot;该设的审批&quot;">​</a></h2><p><a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">approvals-security-and-privacy</a> 要求把常驻边界写进 Bot 描述，并把这些动作留在审批后面：</p><ul><li>发消息或邀请</li><li>发布内容</li><li>购买和资金划转</li><li>删除或覆盖数据</li><li>改权限</li><li>改生产</li><li>接受法律条款</li></ul><p>Auto Review 可用时：<strong>Require Approval</strong> 永远压过 <strong>Always Allow</strong>。不要写「浏览器里什么都允许」这种宽规则。</p><h2 id="费用-只写官方页上的话" tabindex="-1">费用（只写官方页上的话） <a class="header-anchor" href="#费用-只写官方页上的话" aria-label="Permalink to &quot;费用（只写官方页上的话）&quot;">​</a></h2><p><a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">faq</a> 说能否用、怎么计费取决于账号和套餐；Grok Bot 订阅含每周用量，符合条件的账号可以按模型和 token 成本加购按需用量。<a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a> 当前列出 Cursor Ultra $200 / 月、Cursor Premium Teams $120 / 席 / 月，并写 SuperGrok Heavy / Cursor Ultra 已包含 Grok Bot。本页<strong>不</strong>臆造 SuperGrok Heavy 的价格或 token 配额。</p><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a></td><td>Bot 是什么</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/get-started</a></td><td>安装、登录、第一次派活</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/files-and-results" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/files-and-results</a></td><td>附件与结果</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/computer-and-apps</a></td><td>共享电脑、connector、<code>/workspace</code></td></tr><tr><td><a href="https://docs.x.ai/grok-bot/approvals-security-and-privacy" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/approvals-security-and-privacy</a></td><td>审批、本机、隐私</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/faq</a></td><td>平台、记忆、费用、删除</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/teams-and-enterprises" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/teams-and-enterprises</a></td><td>每人一台电脑、组织控制</td></tr><tr><td><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a></td><td>营销页和下载</td></tr><tr><td><a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">x.ai/news/introducing-grok-bot</a></td><td>发布公告（2026-08-11，beta）</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">Grok 学习地图</a> — 家族决策树</li><li><a href="./grok-cli.html">Grok Build 教程</a> — 终端编程 Agent</li><li><a href="./grok-glossary.html">术语表</a> — 名字怎么撞车</li></ul>',46)])])}const u=r(i,[["render",n]]);export{f as __pageData,u as default};
